export function InspectorPattern({
  heading = "{{heading}}",
  itemName = "{{itemName}}",
  accent = "{{accent}}",
  showInspector = {{showInspector}},
  panelWidth = {{panelWidth}},
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", display: "flex", maxWidth: 420, width: 420, border: "1px solid #24143020", borderRadius: 12, overflow: "hidden", boxSizing: "border-box" }}>
      <main aria-label={heading} style={{ flex: 1, padding: 14, background: "#fff", minWidth: 0 }}>
        <h3 style={{ margin: "0 0 10px", fontSize: 14, fontWeight: 700 }}>{heading}</h3>
        <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
          <li aria-current="true" style={{ padding: "6px 8px", borderRadius: 6, background: accent, fontWeight: 700 }}>{itemName}</li>
          <li style={{ padding: "6px 8px", borderRadius: 6 }}>Hero image</li>
          <li style={{ padding: "6px 8px", borderRadius: 6 }}>Footer</li>
        </ul>
      </main>
      {showInspector && (
        <aside aria-label="Inspector" style={{ width: panelWidth, flexShrink: 0, background: "#FAF7F2", borderLeft: "1px solid #24143020", padding: 14, boxSizing: "border-box" }}>
          <h4 style={{ margin: "0 0 8px", fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".03em", color: "#241430a0" }}>Properties</h4>
          <dl style={{ margin: 0 }}>
            {[["Name", itemName], ["Opacity", "100%"], ["Locked", "No"]].map(([k, v]) => (
              <div key={k} style={{ padding: "4px 0", borderBottom: "1px solid #24143014" }}>
                <dt style={{ fontSize: 11, color: "#241430a0", margin: 0 }}>{k}</dt>
                <dd style={{ margin: "1px 0 0", fontWeight: 600 }}>{v}</dd>
              </div>
            ))}
          </dl>
        </aside>
      )}
    </div>
  );
}
